import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.B4hAkGey.js";const u=JSON.parse('{"title":"EP.16 UDP 之上的握手与加密","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.16-handwritten-dtls-srtp.md","filePath":"comics/EP.16-handwritten-dtls-srtp.md","lastUpdated":1792683941000}'),n={name:"comics/EP.16-handwritten-dtls-srtp.md"};function l(r,t,i,p,d,c){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="ep-16-udp-之上的握手与加密" tabindex="-1">EP.16 UDP 之上的握手与加密 <a class="header-anchor" href="#ep-16-udp-之上的握手与加密" aria-label="Permalink to &quot;EP.16 UDP 之上的握手与加密&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/16-handwritten-dtls-srtp/basics">模块十六 · 手写 DTLS + SRTP</a> 动手演示：<a href="./../guide/16-handwritten-dtls-srtp/practice">模拟 DTLS 握手与 SRTP 加解密</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君抓包看自研 Demo 的媒体流量：RTP 头（<code>80 60 …</code>）清晰可辨，payload 却是一堆随机字节——&quot;我发的明明是 hello，被劫持了？&quot;其实是 WebRTC 强制加密，没有密钥就只能看到密文。</td></tr><tr><td>② 揭秘</td><td>码叔拆解：DTLS 就是&quot;UDP 上的 TLS&quot;。ClientHello → HelloVerifyRequest+cookie → 带 cookie 重发 → ServerHello/Certificate → ECDHE 密钥交换，最后用 <code>EXTRACTOR-dtls_srtp</code> 标签导出 SRTP 密钥。证书不用 CA，靠 SDP <code>a=fingerprint</code> 带外比对指纹。</td></tr><tr><td>③ 实证</td><td>像素酱跑 Node.js 模拟：ECDHE 握手 → 校验证书指纹 == SDP <code>a=fingerprint</code> → <code>srtp.protect()</code> / <code>unprotect()</code>。打印显示：线上包里 RTP 头保持明文，payload 变随机字节，末尾多出 10 字节 auth tag。</td></tr><tr><td>④ 结案</td><td>码叔总结：DTLS 管握手、SRTP 管加密、指纹校验是信任锚。坑点三条：指纹不匹配=中间人、verify-then-decrypt 顺序不能反、auth tag 别乱截 32-bit。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-dtls-握手为什么需要-cookie-helloverifyrequest" tabindex="-1">① DTLS 握手为什么需要 cookie（HelloVerifyRequest） <a class="header-anchor" href="#_1-dtls-握手为什么需要-cookie-helloverifyrequest" aria-label="Permalink to &quot;① DTLS 握手为什么需要 cookie（HelloVerifyRequest）&quot;">​</a></h3><p>TLS 跑在 TCP 上，三次握手已经验证了源地址真实性；DTLS 跑在 UDP 上，UDP 无连接、源地址可伪造——攻击者可以伪造受害者 IP 发一个 ClientHello，服务器就会回一个<strong>更大的</strong> Certificate 消息砸向受害者（DoS 放大攻击）。</p><p>DTLS（RFC 6347）的解法是<strong>无状态 cookie 机制</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client                    Server</span></span>
<span class="line"><span>  |── ClientHello ────────&gt;|            （无 cookie）</span></span>
<span class="line"><span>  |&lt;── HelloVerifyRequest ─|            （服务端回一个 cookie，自己不存状态）</span></span>
<span class="line"><span>  |── ClientHello+cookie ─&gt;|            （客户端原样带回，证明&quot;我能收到发到我 IP 的包&quot;）</span></span>
<span class="line"><span>  |&lt;── ServerHello … ──────|            （验证通过，才开始真正的握手）</span></span></code></pre></div><p>cookie 通常是对客户端 IP 的 HMAC，服务端<strong>不保存任何状态</strong>，验证通过才分配握手资源。这和 SYN cookie 是同一个思想。</p><h3 id="_2-密钥导出-extractor-dtls-srtp" tabindex="-1">② 密钥导出：EXTRACTOR-dtls_srtp <a class="header-anchor" href="#_2-密钥导出-extractor-dtls-srtp" aria-label="Permalink to &quot;② 密钥导出：EXTRACTOR-dtls_srtp&quot;">​</a></h3><p>DTLS 握手产出的是 TLS session 密钥，SRTP 用的密钥<strong>不直接用</strong>它，而是通过 TLS Exporter（RFC 5705 / 5764）导出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>key_material = TLS_exporter(</span></span>
<span class="line"><span>    label = &quot;EXTRACTOR-dtls_srtp&quot;,</span></span>
<span class="line"><span>    context = &quot;&quot;,</span></span>
<span class="line"><span>    length = 2 × (master_key_len + master_salt_len)</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>// 按序切成四段：client_write_key | server_write_key</span></span>
<span class="line"><span>//               | client_write_salt | server_write_salt</span></span></code></pre></div><p>双向各拿各的 key+salt，发送用自己的 <code>client_write_key</code>，接收用对端的。这样做的好处：SRTP 密钥与 TLS 会话密钥<strong>密码学隔离</strong>，就算 SRTP 密钥泄露也反推不出 TLS 密钥。</p><h3 id="_3-srtp-aes-cm-的-iv-构造" tabindex="-1">③ SRTP AES-CM 的 IV 构造 <a class="header-anchor" href="#_3-srtp-aes-cm-的-iv-构造" aria-label="Permalink to &quot;③ SRTP AES-CM 的 IV 构造&quot;">​</a></h3><p>SRTP 默认用 AES-CM（Counter Mode）：加密 = 用 AES 生成 keystream 再和 payload 异或。 keystream 的输入 IV 不是随机的，而是从<strong>包内可推导的公开字段</strong>构造：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IV = (salt &lt;&lt; 16) ⊕ (SSRC &lt;&lt; 64) ⊕ (packet_index &lt;&lt; 16)</span></span>
<span class="line"><span>packet_index = (ROC &lt;&lt; 16) | sequence_number</span></span></code></pre></div><ul><li>每个包的 seq 不同 → IV 不同 → keystream 不同，天然满足 CTR 模式&quot;nonce 不重用&quot;的硬性要求；</li><li>收端按同样公式重建 IV，所以 <strong>IV 不需要随包传输</strong>，零开销；</li><li>RTP 头不加密（QoS 设备、SFU 要读 SSRC/seq/pt），但会被 auth tag 覆盖保护——改头也会验签失败。</li></ul><h3 id="_4-重放保护与-roc" tabindex="-1">④ 重放保护与 ROC <a class="header-anchor" href="#_4-重放保护与-roc" aria-label="Permalink to &quot;④ 重放保护与 ROC&quot;">​</a></h3><p><code>sequence_number</code> 只有 16 位，65535 之后就回绕。SRTP 用 <strong>ROC（Roll-Over Counter，回绕计数器）</strong> 把包索引扩展成 48 位：<code>index = ROC × 65536 + seq</code>。ROC 不出现在包里，由收发双方各自维护——seq 从 65535 跳回小数值时 ROC++。</p><p>重放保护靠一个<strong>滑动窗口</strong>（默认 64 包）：记录已验证通过的最大 index，凡是落在窗口左侧（太旧）或已标记收过的包，直接丢弃。注意顺序：<strong>先验 auth tag，再查重放窗口</strong>——没验签的包不得更新窗口状态，否则攻击者可以用伪造包把窗口&quot;推走&quot;，造成合法包被误杀。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：为什么 WebRTC 不用 CA 证书体系？指纹不匹配意味着什么？</strong> WebRTC 两端是浏览器，没有固定域名可绑证书，所以用<strong>自签名证书 + SDP <code>a=fingerprint</code> 带外比对</strong>。信令通道（你的 HTTPS/WSS）必须是可信的，JS 把 SDP 里的指纹和 DTLS 握手收到的证书指纹逐字节比对。<strong>不匹配 = 有人在中间人转发</strong>（比如抓包代理、配置错误的 SFU），必须直接挂断。</li><li><strong>Q：收到 SRTP 包，先解密还是先验签？</strong> <strong>永远 verify-then-decrypt</strong>。先算 HMAC-SHA1 比对 auth tag，通过后才解密。反过来的话，攻击者可以构造任意密文观察你的解密反应（padding oracle / 时序侧信道），逐字节推出明文。验签失败的包直接丢，不产生任何解密行为。</li><li><strong>Q：auth tag 可以截断吗？截多短算危险？</strong> SRTP 允许 80-bit（默认）或 32-bit 标签。32-bit 意味着伪造一个合法包的期望尝试次数只有 2³²≈40 亿次——对在线暴力来说并非遥不可及；而 80-bit 是 2⁸⁰。语音小流苏场景曾为省带宽用 32-bit，<strong>自己实现时一律用 80-bit</strong>，别为每包 6 字节冒被注入假包的风险。</li></ul><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>DTLS 握手中 HelloVerifyRequest + cookie 解决的是什么攻击？为什么 TLS 不需要这一步？</li><li>SRTP 的加密密钥从哪来？写出 AES-CM 模式下 IV 的构造公式，并说明为什么 IV 不用随包发送。</li><li>一个 SRTP 会话里 seq 回绕了两次，收端收到 seq=100 的包，怎么判断它属于哪一轮？如果这时收到一个&quot;重复&quot;的包，正确处理顺序是什么？</li></ol><details><summary>答案</summary><ol><li><p>解决<strong>基于源地址伪造的 DoS 放大攻击</strong>：UDP 无连接，攻击者可伪造受害者 IP 发 ClientHello，诱导服务器把更大的 Certificate 消息发到受害者。cookie 要求客户端证明自己能收到发往其 IP 的包（带回服务端签发的 HMAC cookie），且服务端验证前不分配任何状态。TLS 跑在 TCP 上，三次握手已完成源地址验证（伪造 IP 收不到 SYN-ACK，握手无法完成），所以不需要。</p></li><li><p>密钥来自 <strong>DTLS 握手后的 TLS Exporter</strong>：<code>TLS_exporter(&quot;EXTRACTOR-dtls_srtp&quot;, &quot;&quot;, len)</code>，导出后切成 client/server 双向的 master key + master salt。IV 构造公式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IV = (salt &lt;&lt; 16) ⊕ (SSRC &lt;&lt; 64) ⊕ (index &lt;&lt; 16)，index = (ROC &lt;&lt; 16) | seq</span></span></code></pre></div><p>因为 SSRC、ROC、seq 都是收发双方<strong>各自可推导</strong>的（SSRC 在头里明文，seq 在头里明文，ROC 本地维护），收端用同一公式重建 IV，所以无需随包传输，省带宽。同时每包 seq 唯一 → IV 唯一 → keystream 不重用，满足 CTR 模式安全前提。</p></li><li><p>收端维护 ROC（回绕计数器）：看到 seq 从接近 65535 跳回小数值就 ROC++，包的真实索引 = <code>ROC × 65536 + seq</code>。回绕两次后 ROC=2，seq=100 的包 index = 2×65536+100 = 131172。</p><p>收到&quot;重复&quot;包（index 落在已收记录里）的正确处理顺序：</p><ol><li><strong>先验 auth tag</strong>（HMAC-SHA1），不通过直接丢，<strong>不得更新任何状态</strong>；</li><li>验签通过后<strong>查重放窗口</strong>：该 index 是否已标记收过 / 是否落在窗口左侧；</li><li>是重放 → 丢弃并计重放统计；不是 → 更新窗口位图，再交给 unprotect 解密。</li></ol><p>顺序反了（先更新窗口再验签）会让攻击者用伪造包污染窗口，把合法包误判成重放——这也是&quot;verify-then-decrypt&quot;铁律在重放保护上的延伸。</p></li></ol></details>`,26)])])}const g=e(n,[["render",l]]);export{u as __pageData,g as default};
